/**
 * Config, validation and constant types the UI works with, generated from
 * the Rust model (crates/airband-config, crates/airband-validate) into
 * src/generated by `cargo test`. Never hand-edit src/generated.
 *
 * Output variants are re-exported with their `type` tag included (the
 * generated structs carry only their fields; the tag lives on the `Output`
 * union), so `const o: FileOutput = { type: "file", ... }` keeps working.
 */
import type { FileOutput as FileFields } from "../generated/FileOutput";
import type { IcecastOutput as IcecastFields } from "../generated/IcecastOutput";
import type { MixerOutput as MixerFields } from "../generated/MixerOutput";
import type { MixerRemoteOutput as MixerRemoteFields } from "../generated/MixerRemoteOutput";
import type { PulseOutput as PulseFields } from "../generated/PulseOutput";
import type { RawFileOutput as RawFileFields } from "../generated/RawFileOutput";
import type { UdpStreamOutput as UdpStreamFields } from "../generated/UdpStreamOutput";

export type { RtlAirbandConfig } from "../generated/RtlAirbandConfig";
export type { Device } from "../generated/Device";
export type { DeviceMode } from "../generated/DeviceMode";
export type { Channel } from "../generated/Channel";
export type { MultichannelChannel } from "../generated/MultichannelChannel";
export type { ScanChannel } from "../generated/ScanChannel";
export type { Mixer } from "../generated/Mixer";
export type { MixerRemoteInput } from "../generated/MixerRemoteInput";
export type { RdioScannerConfig } from "../generated/RdioScannerConfig";
export type { Setting } from "../generated/Setting";
export type { ValidationIssue } from "../generated/ValidationIssue";
export type { ValidationResult } from "../generated/ValidationResult";
export type { Severity as IssueSeverity } from "../generated/Severity";

export type PulseOutput = { type: "pulse" } & PulseFields;
export type FileOutput = { type: "file" } & FileFields;
export type RawFileOutput = { type: "rawfile" } & RawFileFields;
export type IcecastOutput = { type: "icecast" } & IcecastFields;
export type UdpStreamOutput = { type: "udp_stream" } & UdpStreamFields;
export type MixerOutput = { type: "mixer" } & MixerFields;
export type MixerRemoteOutput = { type: "mixer_remote" } & MixerRemoteFields;

export type Output = PulseOutput | FileOutput | RawFileOutput | IcecastOutput | UdpStreamOutput | MixerOutput | MixerRemoteOutput;
